package com.procurement.service; import com.procurement.entity.*; import com.procurement.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class NotificationService { private final NotificationRepository repo; public NotificationService(NotificationRepository repo){this.repo=repo;} public void create(Farmer f,Booking b,NotificationType t,String msg){Notification n=new Notification();n.setFarmer(f);n.setBooking(b);n.setType(t);n.setChannel(NotificationChannel.APP);n.setMessage(msg);n.setStatus(NotificationStatus.SENT);n.setSentAt(java.time.LocalDateTime.now());repo.save(n);} public List<Notification> mine(Long farmerId){return repo.findByFarmerIdOrderByCreatedAtDesc(farmerId);} }
